# concepts:
# color transformation, run modification, recoloring

# description:
# For each horizontal or vertical run of cyan (color-6) cells, recolor up to 3 cells from each end to yellow (color-4).
# The number of cells recolored from each end is capped at half the run's length.

def main(input_grid: np.ndarray) -> np.ndarray:
    output_grid = np.copy(input_grid)

    # Horizontal runs
    for row in range(input_grid.shape[0]):
        current_run = []
        for col in range(input_grid.shape[1]):
            if input_grid[row, col] == Color.TEAL:
                current_run.append(col)
            else:
                if len(current_run) > 0:
                    recolor_run(output_grid, row, current_run, is_horizontal=True)
                current_run = []
        if len(current_run) > 0:
            recolor_run(output_grid, row, current_run, is_horizontal=True)

    # Vertical runs
    for col in range(input_grid.shape[1]):
        current_run = []
        for row in range(input_grid.shape[0]):
            if input_grid[row, col] == Color.TEAL:
                current_run.append(row)
            else:
                if len(current_run) > 0:
                    recolor_run(output_grid, col, current_run, is_horizontal=False)
                current_run = []
        if len(current_run) > 0:
            recolor_run(output_grid, col, current_run, is_horizontal=False)

    return output_grid

def recolor_run(grid, index, run, is_horizontal):
    run_length = len(run)
    recolor_length = min(3, run_length // 2)

    for i in range(recolor_length):
        if is_horizontal:
            grid[index, run[i]] = Color.YELLOW
            grid[index, run[-i-1]] = Color.YELLOW
        else:
            grid[run[i], index] = Color.YELLOW
            grid[run[-i-1], index] = Color.YELLOW

def generate_input() -> np.ndarray:
    n, m = np.random.randint(5, 15), np.random.randint(5, 15)
    grid = np.zeros((n, m), dtype=int)

    num_cyan_runs = np.random.randint(1, min(n, m))
    for _ in range(num_cyan_runs):
        is_horizontal = np.random.choice([True, False])

        if is_horizontal:
            row = np.random.randint(n)
            start_col = np.random.randint(m)
            run_length = np.random.randint(2, m - start_col)
            grid[row, start_col:start_col + run_length] = Color.TEAL
        else:
            col = np.random.randint(m)
            start_row = np.random.randint(n)
            run_length = np.random.randint(2, n - start_row)
            grid[start_row:start_row + run_length, col] = Color.TEAL

    return grid

from common import *

import numpy as np
from typing import *

# concepts:
# color transformation, run modification, recoloring

# description:
# For each horizontal or vertical run of cyan (color-6) cells, recolor up to 3 cells from each end to yellow (color-4).
# The number of cells recolored from each end is capped at half the run's length.

def main(input_grid: np.ndarray) -> np.ndarray:
    output_grid = np.copy(input_grid)

    # Process horizontal runs
    for i in range(output_grid.shape[0]):
        start, end = None, None
        for j in range(output_grid.shape[1]):
            if output_grid[i, j] == Color.TEAL:
                if start is None:
                    start = j
                end = j
            else:
                if start is not None and end is not None:
                    # Recolor the run found
                    recolor_run(output_grid, i, start, end, horizontal=True)
                start, end = None, None
        # Check if a run ends at the last column
        if start is not None and end is not None:
            recolor_run(output_grid, i, start, end, horizontal=True)

    # Process vertical runs
    for j in range(output_grid.shape[1]):
        start, end = None, None
        for i in range(output_grid.shape[0]):
            if output_grid[i, j] == Color.TEAL:
                if start is None:
                    start = i
                end = i
            else:
                if start is not None and end is not None:
                    # Recolor the run found
                    recolor_run(output_grid, start, end, j, horizontal=False)
                start, end = None, None
        # Check if a run ends at the last row
        if start is not None and end is not None:
            recolor_run(output_grid, start, end, j, horizontal=False)

    return output_grid

def recolor_run(grid, start, end, index, horizontal):
    run_length = end - start + 1
    recolor_length = min(3, run_length // 2)
    if horizontal:
        for k in range(recolor_length):
            grid[index, start + k] = Color.YELLOW
            grid[index, end - k] = Color.YELLOW
    else:
        for k in range(recolor_length):
            grid[start + k, index] = Color.YELLOW
            grid[end - k, index] = Color.YELLOW

def generate_input() -> np.ndarray:
    # Random size of the grid
    height = np.random.randint(5, 10)
    width = np.random.randint(5, 10)

    # Initialize grid with random colors
    grid = np.random.choice(list(Color.NOT_BLACK), (height, width))

    # Randomly place horizontal and vertical cyan runs
    num_horizontal_runs = np.random.randint(1, height // 2 + 1)
    num_vertical_runs = np.random.randint(1, width // 2 + 1)

    # Create horizontal cyan runs
    for _ in range(num_horizontal_runs):
        row = np.random.randint(0, height)
        start_col = np.random.randint(0, width - 2)
        run_length = np.random.randint(2, width - start_col)
        grid[row, start_col:start_col + run_length] = Color.TEAL

    # Create vertical cyan runs
    for _ in range(num_vertical_runs):
        col = np.random.randint(0, width)
        start_row = np.random.randint(0, height - 2)
        run_length = np.random.randint(2, height - start_row)
        grid[start_row:start_row + run_length, col] = Color.TEAL

    return grid
